# атрибуция раньше креативов

Оба практика спринта ставят атрибуцию условием масштаба. Урбан собрал свою (отпечаток устройства при скачивании и открытии, «почти сто процентов» склейки) и отдаёт площадке чистые данные. Кумар не доверяет площадке и сам сшивает, что кому показано. Вывод общий: без атрибуции не масштабировать.

## минимум для харнесса
1. у каждой единицы контента код из [[{rule} creative-codes]];
2. код уходит в `utm_content` каждой ссылки;
3. регистрации и оплаты сводятся по коду раз в неделю ([[{skill} weekly-loop]]);
4. вердикт ставится по оплатам; дешёвый лид без оплаты – fake winner;
5. пока оплаты не сведены, новый канал не масштабируем.

#!/usr/bin/env node
// Level-1 evals: deterministic checks over outputs/ (no model, seconds).
//   node bin/check.mjs                 → evals/{eval} checks – <today>.md, exit 1 on a hard fail
//   node bin/check.mjs --golden        → regression run over evals/{eval} golden-set.md
//   node bin/check.mjs --date 2026-09-29 --json
// Stop-words come from rules/{rule} anti-slop.md, facts from context/{context} truth-pack.md and sources/.
import fs from 'node:fs';
import path from 'node:path';

const root = process.cwd();
const argv = process.argv.slice(2);
const opt = (n, d) => { const i = argv.indexOf(`--${n}`); return i >= 0 ? argv[i + 1] : d; };
const today = opt('date', new Date().toISOString().slice(0, 10));
const read = (p) => { try { return fs.readFileSync(path.join(root, p), 'utf8'); } catch { return ''; } };
const walk = (dir) => { try { return fs.readdirSync(path.join(root, dir), { recursive: true }).map(String).map((f) => path.join(dir, f)); } catch { return []; } };

// ---------- rule sources ----------
const antiSlop = read('rules/{rule} anti-slop.md');
const stopSection = (antiSlop.split('## стоп-лист слов')[1] || '').split('\n## ')[0];
const STOP_WORDS = stopSection.split('\n').join(' ').split('·').map((w) => w.trim().toLowerCase()).filter((w) => w && w.length > 3)
  .map((w) => w.split(' ').map((x) => x.slice(0, Math.max(5, x.length - 2))).join(' '));
const CUSHIONS = ['честно говоря', 'стоит отметить', 'важно понимать', 'давайте разберёмся', 'давайте разберемся', 'ниже –', 'в этом посте', 'секрет в том', 'и вот что важно'];
const ANTITHESIS = [
  /(^|[\s.,;:!?«"(])не\s+(?:просто\s+|только\s+)?[^.,;:!?\n]{1,40}?,\s*а\s+/i,
  /это\s+не\s+[^.;:!?\n]{1,40}?\s+[–-]\s+это/i,
  /вместо\s+[^.;:!?\n]{1,40}?\s+[–-]\s+/i,
];
const LENGTH = { linkedin: [700, 1700], telegram: [300, 1600] };

// ---------- facts corpus: number + unit keys ----------
const NUM = /(\$|€)?(\d+(?:[  ]\d{3})*(?:[.,]\d+)?)(?:\s?[–-]\s?\d+)?\s*(%|\$|€|[a-zа-яё]+)?/gi;
const keyOf = (m) => `${m[2].replace(/[  ]/g, '').replace(',', '.')}|${(m[3] || m[1] || '').toLowerCase().slice(0, 3)}`;
const corpusText = [read('context/{context} truth-pack.md'), ...walk('sources').filter((f) => f.endsWith('.md')).map(read), ...walk('nuclei').filter((f) => f.endsWith('.md')).map(read)].join('\n');
const FACT_KEYS = new Set([...corpusText.matchAll(NUM)].map(keyOf));
const FACT_NUMS = new Set([...corpusText.matchAll(NUM)].map((m) => m[2].replace(/[  ]/g, '')));

function frontmatter(t) {
  const m = /^---\n([\s\S]*?)\n---\n?/.exec(t);
  const fm = {};
  if (m) m[1].split('\n').forEach((l) => { const i = l.indexOf(':'); if (i > 0) fm[l.slice(0, i).trim()] = l.slice(i + 1).trim().replace(/^["']|["']$/g, ''); });
  return { fm, body: m ? t.slice(m[0].length) : t };
}

// text-level checks shared by drafts and the golden set
function textChecks(body) {
  const lower = body.toLowerCase();
  const found = {
    emdash: (body.match(/—/g) || []).length,
    antithesis: ANTITHESIS.map((re) => (re.exec(body) || [])[0]).filter(Boolean).map((s) => s.trim().slice(0, 60)),
    stopwords: STOP_WORDS.filter((w) => lower.includes(w)),
    cushions: CUSHIONS.filter((c) => lower.includes(c)),
  };
  return found;
}

function checkDraft(file) {
  const { fm, body: raw } = frontmatter(read(file));
  const body = raw.replace(/^\|\s*\d+\s*\|/gm, '|'); // slide numbers of briefs are not facts
  const t = textChecks(body);
  const missing = ['nucleus', 'channel', 'segment', 'code', 'status'].filter((k) => !fm[k]);
  const codeOk = /^P\d-H\d-A\d-F\d$/.test(fm.code || '');
  const len = body.replace(/\s+/g, ' ').trim().length;
  const bounds = LENGTH[(fm.channel || '').toLowerCase()];
  const lengthOk = !bounds || (len >= bounds[0] && len <= bounds[1]);
  // a number passes when the same number+unit is in the facts corpus, or when it is >= 10 and appears there at all;
  // small numbers need the unit to match ("в 3 раза" fails even though "3 недели" exists)
  const unsourced = [...body.matchAll(NUM)].filter((m) => {
    const n = m[2].replace(/[  ]/g, '');
    if (/^[12]$/.test(n) || FACT_KEYS.has(keyOf(m))) return false;
    return !(FACT_NUMS.has(n) && (parseFloat(n.replace(',', '.')) >= 10 || m[3] === undefined));
  }).map((m) => m[0].trim()).filter((s) => !/^P\d|^H\d|^A\d|^F\d/.test(s));
  const links = (body.match(/https?:\/\//g) || []).length;
  const hard = t.emdash > 0 || t.antithesis.length > 0 || t.stopwords.length > 0 || missing.length > 0 || !codeOk;
  const soft = t.cushions.length > 0 || !lengthOk || unsourced.length > 0 || ((fm.channel === 'linkedin') && links > 0);
  return { file, channel: fm.channel || '', code: fm.code || '', len, lengthOk, missing, codeOk, links, unsourced, ...t, verdict: hard ? 'fail' : soft ? 'warn' : 'pass' };
}

// ---------- golden set regression ----------
function golden() {
  const text = read('evals/{eval} golden-set.md');
  // `golden pass|fail` – the code catches it; `golden judge` – only the LLM judge does, the code skips it
  const blocks = [...text.matchAll(/```golden (pass|fail)(?::\s*([^\n]*))?\n([\s\S]*?)```/g)];
  const judge = [...text.matchAll(/```golden judge\b/g)].length;
  let ok = 0;
  const rows = blocks.map(([, expect, why, body], i) => {
    const t = textChecks(body);
    const got = t.emdash || t.antithesis.length || t.stopwords.length || t.cushions.length ? 'fail' : 'pass';
    const pass = got === expect;
    if (pass) ok++;
    return `${pass ? '✓' : '✗'} пример ${i + 1}: ждали ${expect}${why ? ` (${why.trim()})` : ''}, получили ${got}`;
  });
  console.log(rows.join('\n'));
  console.log(`golden set: ${ok}/${blocks.length}${judge ? ` · ещё ${judge} для судьи (код их не проверяет, смотрит slop-check)` : ''}`);
  process.exit(ok === blocks.length ? 0 : 1);
}
if (argv.includes('--golden')) golden();

// ---------- run over outputs ----------
// plates 3:1 are design briefs, their words are checked inside the post they illustrate
const drafts = walk('outputs').filter((f) => f.endsWith('.md') && !f.includes('/covers/'));
const results = drafts.map(checkDraft);
if (argv.includes('--json')) { console.log(JSON.stringify(results, null, 2)); process.exit(0); }

const mark = (b) => (b ? '✓' : '✗');
const rows = results.map((r) => `| [[${path.basename(r.file, '.md')}]] | ${r.emdash ? `✗ ${r.emdash}` : '✓'} | ${r.antithesis.length ? `✗ «${r.antithesis[0]}»` : '✓'} | ${r.stopwords.length ? `✗ ${r.stopwords.join(', ')}` : '✓'} | ${r.cushions.length ? `! ${r.cushions.join(', ')}` : '✓'} | ${r.missing.length ? `✗ ${r.missing.join(', ')}` : '✓'} | ${mark(r.codeOk)} ${r.code} | ${r.lengthOk ? '✓' : '!'} ${r.len} | ${r.unsourced.length ? `! ${r.unsourced.slice(0, 3).join(', ')}` : '✓'} | **${r.verdict}** |`);
const counts = results.reduce((a, r) => ({ ...a, [r.verdict]: (a[r.verdict] || 0) + 1 }), {});
const report = `---
title: проверки кодом
generated_by: bin/check.mjs
date: ${today}
---
# проверки кодом · ${today}

Уровень 1 из [[{rule} evals]]. Стоп-слова берутся из [[{rule} anti-slop]], факты – из [[{context} truth-pack]] и \`sources/\`. ✗ – жёсткий провал, ! – предупреждение.

| черновик | тире | антитеза | стоп-слова | подушки | frontmatter | код | длина | числа без источника | итог |
|---|---|---|---|---|---|---|---|---|---|
${rows.join('\n')}

итог: pass ${counts.pass || 0} · warn ${counts.warn || 0} · fail ${counts.fail || 0}. провалы уходят автору до судьи ([[{skill} slop-check]]).
`;
const out = `evals/{eval} checks – ${today}.md`;
fs.mkdirSync(path.join(root, 'evals'), { recursive: true });
fs.writeFileSync(path.join(root, out), report);
console.log(`${out} · pass ${counts.pass || 0} · warn ${counts.warn || 0} · fail ${counts.fail || 0}`);
process.exit(counts.fail ? 1 : 0);

{
  "hooks": {
    "PreToolUse": [
      {
        "matcher": "Write|Edit",
        "hooks": [
          { "type": "command", "command": "node bin/gate-approved.mjs" }
        ]
      }
    ]
  }
}

#!/usr/bin/env node
// Claude Code PreToolUse hook: blocks `status: approved` in outputs/*.md
// until the newest checks report has a passing row for that file.
// Blocks through both channels: exit 2 + stderr, and a JSON deny on stdout.
// Escape hatch: HARNESS_GATE_OK=1 (only when the human says so).
import fs from 'node:fs';
import path from 'node:path';

const deny = (reason) => {
  process.stdout.write(JSON.stringify({
    hookSpecificOutput: { hookEventName: 'PreToolUse', permissionDecision: 'deny', permissionDecisionReason: reason },
  }) + '\n');
  process.stderr.write(`gate-approved: ${reason}\n`);
  process.exit(2);
};
const allow = () => process.exit(0);

if (process.env.HARNESS_GATE_OK === '1') allow();

let input = {};
try { input = JSON.parse(fs.readFileSync(0, 'utf8') || '{}'); } catch { allow(); } // unreadable input is not our business

const tool = input.tool_name;
const ti = input.tool_input || {};
if (tool !== 'Write' && tool !== 'Edit') allow();

const root = process.cwd();
const file = ti.file_path ? path.resolve(root, ti.file_path) : '';
const rel = file ? path.relative(root, file).split(path.sep) : [];
if (rel[0] !== 'outputs' || !file.endsWith('.md')) allow();

const text = tool === 'Write' ? ti.content : ti.new_string;
if (!/^status:\s*["']?approved["']?\s*$/m.test(text || '')) allow();

// newest report by date in the file name
const evalsDir = path.join(root, 'evals');
let reports = [];
try {
  reports = fs.readdirSync(evalsDir)
    .filter((f) => /^\{eval\} checks – \d{4}-\d{2}-\d{2}\.md$/.test(f))
    .sort();
} catch { /* no evals dir */ }
const base = path.basename(file, '.md');
const hint = 'Запусти `node bin/check.mjs`, поправь провалы, повтори. Выключатель HARNESS_GATE_OK=1 включает только человек.';
if (!reports.length) deny(`нет отчёта проверок в evals/. ${hint}`);

const newest = reports[reports.length - 1];
const report = fs.readFileSync(path.join(evalsDir, newest), 'utf8');
const row = report.split('\n').find((l) => l.startsWith('|') && l.includes(`[[${base}]]`));
if (!row) deny(`в отчёте «${newest}» нет строки для «${base}». ${hint}`);
const verdict = (/\*\*(pass|warn|fail)\*\*\s*\|?\s*$/.exec(row.trim()) || [])[1];
if (verdict !== 'pass') deny(`в отчёте «${newest}» вердикт для «${base}»: ${verdict || 'не найден'}. Нужен pass. ${hint}`);
allow();

#!/usr/bin/env node
// Ask-before-create: lists existing files whose names share a word (>= 4 letters) with the new name.
//   node bin/guard-new.mjs <skill|nucleus|automation|rule|tool> <name>
// Exit 1 when matches are found (extend the existing file), 0 when the name is free.
import fs from 'node:fs';
import path from 'node:path';

const DIRS = { skill: 'skills', nucleus: 'nuclei', automation: 'automations', routine: 'automations', rule: 'rules', tool: 'tools' };
const [type, ...rest] = process.argv.slice(2);
const name = rest.join(' ');
if (!DIRS[type] || !name) {
  console.error(`usage: node bin/guard-new.mjs <${Object.keys(DIRS).join('|')}> <name>`);
  process.exit(2);
}

const words = (s) => new Set(s.toLowerCase().replace(/^\{[^}]*\}\s*/, '').split(/[^a-zа-яё]+/i).filter((w) => w.length >= 4));
const mine = words(name);
const dir = path.join(process.cwd(), DIRS[type]);
let files = [];
try { files = fs.readdirSync(dir).filter((f) => f.endsWith('.md')); } catch { /* folder missing: nothing to match */ }

const hits = files
  .map((f) => ({ f, shared: [...words(path.basename(f, '.md'))].filter((w) => mine.has(w)) }))
  .filter((h) => h.shared.length);

if (!hits.length) { console.log(`ok: в ${DIRS[type]}/ нет файлов, похожих на «${name}»`); process.exit(0); }
console.log(`найдено похожее в ${DIRS[type]}/ – дополни существующий файл вместо нового:`);
hits.forEach((h) => console.log(`  ${DIRS[type]}/${h.f}  (общие слова: ${h.shared.join(', ')})`));
process.exit(1);

#!/usr/bin/env node
// Runs gate-approved through the exact command written in .claude/settings.json (same wrapper, no shortcuts).
// Fixtures live in a temp dir; real evals/ is never touched.
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { spawnSync } from 'node:child_process';

const kit = process.cwd();
const settings = JSON.parse(fs.readFileSync(path.join(kit, '.claude/settings.json'), 'utf8'));
const command = settings.hooks.PreToolUse.find((h) => h.matcher === 'Write|Edit').hooks[0].command;

const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'gate-tests-'));
fs.symlinkSync(path.join(kit, 'bin'), path.join(tmp, 'bin'));
fs.mkdirSync(path.join(tmp, 'evals'));
fs.mkdirSync(path.join(tmp, 'outputs'));
const header = '| черновик | итог |\n|---|---|\n';
const reportName = (d) => path.join(tmp, 'evals', `{eval} checks – ${d}.md`);
process.chdir(tmp);

const approved = '---\nstatus: approved\n---\ntext';
const cases = [
  { name: 'Write approved без отчёта', input: { tool_name: 'Write', tool_input: { file_path: 'outputs/{post} none.md', content: approved } }, expect: 'deny' },
  { name: 'Write approved со строкой pass', report: '| [[{post} good]] | **pass** |\n', input: { tool_name: 'Write', tool_input: { file_path: 'outputs/{post} good.md', content: approved } }, expect: 'allow' },
  { name: 'Edit approved при строке fail', report: '| [[{post} bad]] | **fail** |\n', input: { tool_name: 'Edit', tool_input: { file_path: 'outputs/{post} bad.md', new_string: 'status: approved' } }, expect: 'deny' },
  { name: 'Write со статусом draft', input: { tool_name: 'Write', tool_input: { file_path: 'outputs/{post} d.md', content: '---\nstatus: draft\n---\n' } }, expect: 'allow' },
  { name: 'путь вне outputs', input: { tool_name: 'Write', tool_input: { file_path: 'scratch/note.md', content: approved } }, expect: 'allow' },
  { name: 'HARNESS_GATE_OK=1', env: { HARNESS_GATE_OK: '1' }, input: { tool_name: 'Write', tool_input: { file_path: 'outputs/{post} none.md', content: approved } }, expect: 'deny→allow' },
];

let failed = 0;
const lines = cases.map((c, i) => {
  fs.rmSync(reportName('2026-09-29'), { force: true });
  if (c.report) fs.writeFileSync(reportName('2026-09-29'), header + c.report);
  const r = spawnSync('sh', ['-c', command], { input: JSON.stringify(c.input), encoding: 'utf8', env: { ...process.env, HARNESS_GATE_OK: '', ...(c.env || {}) } });
  const wantDeny = c.expect === 'deny';
  const gotDeny = r.status === 2;
  // a deny must use both channels: stderr text and JSON on stdout
  const bothChannels = !gotDeny || (r.stderr.trim() && r.stdout.includes('"permissionDecision":"deny"'));
  const ok = gotDeny === wantDeny && bothChannels && (gotDeny || r.status === 0);
  if (!ok) failed++;
  return `${ok ? 'PASS' : 'FAIL'}  ${i + 1}. ${c.name.padEnd(32)} ждали ${wantDeny ? 'deny ' : 'allow'} · exit ${r.status}`;
});
// the pre-commit gate only works when git can run it: executable bit and core.hooksPath
process.chdir(kit);
const hook = path.join(kit, '.githooks', 'pre-commit');
const exec = fs.existsSync(hook) && (fs.statSync(hook).mode & 0o111) !== 0;
const inRepo = spawnSync('git', ['rev-parse', '--show-toplevel'], { encoding: 'utf8' }).stdout.trim() === kit;
const hooksPath = spawnSync('git', ['config', 'core.hooksPath'], { encoding: 'utf8' }).stdout.trim();
const hookOk = exec && (!inRepo || hooksPath === '.githooks');
if (!hookOk) failed++;
lines.push(`${hookOk ? 'PASS' : 'FAIL'}  ${cases.length + 1}. ${'pre-commit исполняемый и включён'.padEnd(32)} ${!exec ? 'chmod +x .githooks/pre-commit' : inRepo && hooksPath !== '.githooks' ? 'git config core.hooksPath .githooks' : 'ok'}`);
console.log(lines.join('\n'));
console.log(failed ? `\n${failed} из ${cases.length + 1} не совпали` : `\nвсе ${cases.length + 1} PASS`);
fs.rmSync(tmp, { recursive: true, force: true });
process.exit(failed ? 1 : 0);

